stuff_sexProteins <- data.frame(revigo.data_sexProteins);
names(stuff_sexProteins) <- revigo.names;

stuff_sexProteins$value <- as.numeric( as.character(stuff_sexProteins$value) );
stuff_sexProteins$frequency <- as.numeric( as.character(stuff_sexProteins$frequency) );
stuff_sexProteins$uniqueness <- as.numeric( as.character(stuff_sexProteins$uniqueness) );
stuff_sexProteins$dispensability <- as.numeric( as.character(stuff_sexProteins$dispensability) );

# by default, outputs to a PDF file
pdf( file="./8.ENRICHMENTS/StringDB/revigo_treemap_sex_proteins.pdf", width=16, height=14 ) # width and height are in inches
# check the tmPlot command documentation for all possible parameters - there are a lot more
treemap(stuff_sexProteins,
	index = c("representative","description"),
	vSize = "value",
	type = "categorical",
	fontsize.labels = c(0,10),
	fontsize.legend = 10,
	vColor = "representative",
	palette = colorRampPalette(c("mediumpurple4", "lavender"))(60),
	title = "Map of Enriched GO Biological Processes: Sex-related Proteins",
	title.legend = "Parent Nodes",	
	inflate.labels = FALSE,      # set this to TRUE for space-filling group labels - good for posters
	lowerbound.cex.labels = 0,   # try to draw as many labels as possible (still, some small squares may not get a label)
	bg.labels = "#CCCCCCAA",   # define background color of group labels
								 # "#CCCCCC00" is fully transparent, "#CCCCCCAA" is semi-transparent grey, NA is opaque
	position.legend = "right"
)
dev.off()

